"""Generate the public design contract from the same tokens used by native screens."""
from pathlib import Path
import re,html
root=Path(__file__).resolve().parents[1]
theme=(root/'mobile/src/theme.ts').read_text()
layout=dict((k,int(v)) for k,v in re.findall(r'(\w+):\s*(\d+)',theme.split('export const layout =')[1].split('} as const;')[0]))
duo_source=(root/'mobile/src/duo-layout.ts').read_text()
duo_tokens=dict((k,int(v)) for k,v in re.findall(r'(\w+):\s*(\d+)',re.search(r'export const DUO_CHROME=\{([^}]+)\}',duo_source).group(1)))
layout.update((name,duo_tokens[key]) for name,key in re.findall(r'(\w+):\s*DUO_CHROME\.(\w+)',theme))
palette=dict(re.findall(r"(\w+): '(#[a-fA-F0-9]+)'",theme.split('export const palette =')[1].split('} as const')[0]))
heading=re.search(r'heading: \{ fontSize: (\d+), lineHeight: (\d+)',theme).groups()
css=';'.join('--'+k+':'+str(v)+'px' for k,v in layout.items())+';'+';'.join('--'+k+':'+v for k,v in palette.items())+';--headingSize:'+heading[0]+'px;--headingLine:'+heading[1]+'px'
swatches=''.join('<div><i style="background:'+v+'"></i><b>'+k+'</b><code>'+v+'</code></div>' for k,v in palette.items())
rows=''.join('<tr><td>'+k+'</td><td>'+str(v)+'pt</td></tr>' for k,v in layout.items())
tone=(root/'docs/design-guide.md').read_text().split('## 공식 승인 — 2026-11-10 · v1.0',1)[1].split('## 목록 밀도',1)[0]
def tone_line(line):
    text=html.escape(line.strip().removeprefix('- ')).replace('**','')
    return re.sub(r'\[([^\]]+)\]\(([^)]+\.md)\)', lambda m:'<a href="https://github.com/thepmpo/donknow/blob/main/docs/'+m[2]+'">'+m[1]+'</a>', text)
tone_html='<section id="official-tone"><h2>공식 톤앤톤 v1.0 · 2026-11-10</h2>' + ''.join('<p>'+tone_line(line)+'</p>' for line in tone.splitlines() if line.strip()) + '</section>'
audit=(root/'docs/design-guide.md').read_text().split('## 2026-11-12 — 덕 채팅의 새 결과 표시',1)[1].split('## 덕 채팅·iPhone Duo',1)[0]
tone_html='<section id="chat-result-visibility"><h2>새 답변·후보·결과 표시 · 2026-11-12</h2>' + ''.join('<p>'+tone_line(line)+'</p>' for line in audit.splitlines() if line.strip()) + '</section>' + tone_html
current=(root/'docs/design-guide.md').read_text().split('## 덕 채팅·iPhone Duo 적용 승인 — 2026-11-12',1)[1].split('## 공식 승인',1)[0]
tone_html='<section id="current-application"><h2>덕 채팅·iPhone Duo · 2026-11-12</h2>' + ''.join('<p>'+tone_line(line)+'</p>' for line in current.splitlines() if line.strip()) + '</section>' + tone_html
conversation=(root/'docs/design-guide.md').read_text().split('## 덕의 일상 대화 — 2026-11-12',1)[1].split('## 2026-11-12 — 덕 채팅의 새 결과 표시',1)[0]
tone_html='<section id="natural-conversation"><h2>덕의 일상 대화 · 2026-11-12</h2>' + ''.join('<p>'+tone_line(line)+'</p>' for line in conversation.splitlines() if line.strip()) + '</section>' + tone_html
latest=(root/'docs/design-guide.md').read_text().split('## 2026-11-13 — Duo 오른쪽 세로 탭과 예약 메시지',1)[1].split('## 덕의 일상 대화',1)[0]
tone_html='<section id="duo-top-and-scheduled-messages"><h2>Duo 오른쪽 세로 탭과 예약 메시지 · 2026-11-13</h2>' + ''.join('<p>'+tone_line(line)+'</p>' for line in latest.splitlines() if line.strip()) + '</section>' + tone_html
latest_contract=(root/'docs/design-guide.md').read_text().split('## 최신 구현 계약 — 2026-11-13 · 이전 규칙보다 우선',1)[1].split('## 2026-11-13 — Duo',1)[0]
motion_tokens=dict(re.findall(r'(\w+):\s*([\d.]+)',theme.split('export const navigationMotion =')[1].split('} as const;')[0]))
latest_html='<section id="current-contract"><h2>최신 구현 계약 · 다른 채팅과 서비스로 이어받기</h2>'+''.join('<p>'+tone_line(line)+'</p>' for line in latest_contract.splitlines() if line.strip())+'<h3>현재 모션 토큰 · 덕 구현값</h3><table>'+''.join('<tr><td>'+name+'</td><td>'+value+('배' if name=='pressedScale' else 'ms')+'</td></tr>' for name,value in motion_tokens.items())+'</table><p><a href="https://developer.apple.com/design/human-interface-guidelines/tab-bars">Apple Tab bars</a> · <a href="https://developer.apple.com/design/human-interface-guidelines/materials">Apple Materials</a> · <a href="https://developer.apple.com/videos/play/wwdc2025/219/">공식 동작 설명</a></p></section>'
tone_html=latest_html+tone_html
calendar_audit=(root/'docs/design-guide.md').read_text().split('## 캘린더 개선 전체 구현 — 2026-11-13',1)[1]
audit_html='<section id="calendar-audit"><h2>캘린더 개선 전체 구현 · CA-01~20</h2>'+''.join('<p>'+tone_line(line)+'</p>' for line in calendar_audit.splitlines() if line.strip())+'</section>'
tone_html=audit_html+tone_html
reference=(root/'docs/calendar-apple-reference-2026-11-13.md').read_text().split('## 사용자 확정',1)[1].split('## 검증·증거와 재개',1)[0]
tone_html='<section id="calendar-apple-reference"><h2>최신 Apple 캘린더 참고 · 시스템 밝게/어둡게</h2>'+''.join('<p>'+tone_line(line)+'</p>' for line in reference.splitlines() if line.strip())+'</section>'+tone_html
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>덕 디자인 가이드</title><style>:root{CSS}*{box-sizing:border-box}body{margin:0;background:#f2f4f6;color:#191f28;font:16px/1.65 system-ui,sans-serif}main{max-width:1040px;margin:auto;padding:32px 24px 100px}section{background:white;border-radius:24px;padding:24px;margin:24px 0}h1{font-size:32px}h2{font-size:24px;margin-top:0}a{color:#1b64da}.colors{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:16px}.colors div{display:flex;flex-direction:column}i{height:64px;border:1px solid #eee;border-radius:12px}table{border-collapse:collapse;width:100%}td{padding:12px;border-bottom:1px solid #e5e8eb}.phone{max-width:390px;background:#fff;border:1px solid #d1d6db;border-radius:28px;overflow:hidden}.brand{height:var(--headerHeight);padding:8px var(--pageInset);font-size:26px}.heading{padding:var(--pageTop) var(--pageInset) var(--titleBottom);font-size:var(--headingSize);line-height:var(--headingLine);font-weight:700}.content{padding:0 var(--pageInset) var(--sectionGap)}button{width:100%;border:0;border-radius:16px;padding:16px;background:var(--blue700);color:white;font-size:17px;min-height:48px}.actions{display:grid;gap:var(--actionGap)}.secondary{background:var(--blue50);color:var(--blue700)}.glass{min-height:58px;margin:0 var(--navigationInset) var(--navigationBottomGap);border-radius:var(--navigationRadius);padding:8px 4px;display:flex;align-items:center;justify-content:space-around;background:#f9f9f959;backdrop-filter:blur(24px);border:1px solid #b4becd59;font-size:12px}.glass span:first-child{background:#7878801f;border-radius:24px;padding:8px}.phone{padding-bottom:8px}.note{min-height:220px;background:#f9fafb;border-radius:16px;padding:16px;margin:16px 0}</style><main><a href="/project">프로젝트 문서</a><h1>🦆 덕 디자인 가이드</h1><p>공통 토큰 → 공통 헤더·내비게이션·입력·버튼 → 모든 화면. 한 화면만 따로 맞추지 않습니다.</p>OFFICIAL_TONE<section><h2>1. 공통 레이아웃</h2><p>상단은 오리 마크만 표시합니다. 캘린더·할 일·덕·log·내정보 제목은 같은 기준선·좌우 여백·서체를 사용합니다. 탭 이름과 기술 상태를 상단에 중복 표시하지 않습니다.</p><table>ROWS</table><p>실제 값의 기준은 <code>mobile/src/theme.ts</code>와 <code>ScreenHeading.tsx</code>입니다. 토큰을 바꾸면 전체 화면과 이 문서를 함께 갱신합니다.</p></section><section><h2>2. 화면 구조 미리보기</h2><div class="phone"><div class="brand">🦆</div><div class="heading">할 일</div><div class="content"><p>11월 4일 · 오늘 할 일</p><div class="note">메모 입력 공간<br>• 글머리표 뒤에 커서</div><div class="actions"><button>저장</button><button class="secondary">카카오톡 등으로 공유</button></div></div><div class="glass"><span>캘린더</span><span>할 일</span><span>🦆</span><span>log</span><span>내정보</span></div></div><p>일반 iPhone은 좌우12pt·bottom=max(safeInset,8pt)의 떠 있는 둥근 탭 바입니다. 바는 regular Glass, 선택은 평소 중립 강조·누름/끌기 중 Glass입니다. 이 HTML은 구조용 웹 예시이며 native 광학 효과가 아닙니다. 본문 끝 보호 여백과 사용자 접근성 설정을 유지합니다.</p></section><section><h2>3. 색상</h2><div class="colors">SWATCHES</div></section><section><h2>4. 동작 규칙</h2><ul><li>완료는 즉시 표시, 3→2→1 후 350ms 페이드. 동작 줄이기에서는 페이드 생략.</li><li>캘린더는 월±1월·주±7일·일±1일 이동. 날짜 탭은 상세 시트, 년·월 제목은 직접 이동.</li><li>시간은 스피너/선택 목록. 텍스트로 시간을 입력하게 하지 않음.</li><li>메모 최소 높이 220. 글머리표 다음으로 커서를 유지.</li><li>저장·공유·삭제는 actionGap을 공유. 44pt 이상 터치 영역.</li><li>오버레이는 작은 X와 아래로 끌어 닫기. 본문 스크롤은 유지.</li></ul></section><section><h2>5. 변경과 검증</h2><p>간격 변경은 layout 토큰에서 시작하고 ScreenHeading·Page·시트·내비게이션 전체를 검증합니다. 320/390/430 너비와 글자 확대, safe area, 실제 아이폰 블러를 확인합니다. 이 문서는 확인한 토스 토큰을 참고한 덕의 규칙이며 토스 앱의 비공개 규격이나 동일 복제는 아닙니다.</p></section></main></html>'''
(root/'public/design-guide.html').write_text(page.replace('OFFICIAL_TONE',tone_html).replace('CSS',css).replace('ROWS',rows).replace('SWATCHES',swatches))
